# 将 cookie 字符串转换为字典
def cookie_ssp_to_dict(cookie_ssp):
    cookie_dict = {}
    items = cookie_ssp.split(';')
    for item in items:
        if '=' in item:
            key, value = item.strip().split('=', 1)
            cookie_dict[key] = value
    return cookie_dict

cookies_ssp = cookie_ssp_to_dict(cookie_ssp)


